CREATE TABLE IF NOT EXISTS inv_stock_opnames (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, opname_ref VARCHAR(80) NOT NULL UNIQUE, opname_date DATE NOT NULL, branch_id INT UNSIGNED NOT NULL, warehouse_id INT UNSIGNED NOT NULL, note VARCHAR(255) NULL, status ENUM('DRAFT','SUBMITTED','VERIFIED','CANCELLED') NOT NULL DEFAULT 'DRAFT', created_by INT UNSIGNED NOT NULL, verified_by INT UNSIGNED NULL, verified_at DATETIME NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_op_branch FOREIGN KEY(branch_id) REFERENCES branches(id), CONSTRAINT fk_op_wh FOREIGN KEY(warehouse_id) REFERENCES inv_warehouses(id), KEY ix_op_scope(branch_id,warehouse_id,opname_date,status));
CREATE TABLE IF NOT EXISTS inv_stock_opname_lines (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, opname_id INT UNSIGNED NOT NULL, item_id INT UNSIGNED NOT NULL, system_qty DECIMAL(18,3) NOT NULL, physical_qty DECIMAL(18,3) NOT NULL, variance_qty DECIMAL(18,3) NOT NULL, note VARCHAR(255) NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_op_line_h FOREIGN KEY(opname_id) REFERENCES inv_stock_opnames(id) ON DELETE CASCADE, CONSTRAINT fk_op_line_i FOREIGN KEY(item_id) REFERENCES md_items(id), UNIQUE KEY uq_op_item(opname_id,item_id));
INSERT IGNORE INTO permissions(code,name) VALUES ('inventory.opname.view','Lihat stock opname'),('inventory.opname.create','Buat stock opname'),('inventory.opname.update','Ubah stock opname'),('inventory.opname.submit','Kirim stock opname'),('inventory.opname.verify','Verifikasi stock opname'),('inventory.opname.cancel','Batalkan stock opname');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code='inventory.opname.view' WHERE r.name IN ('Owner','Finance');
